/* All battle scenery, tank hulls, projectiles and icons are drawn locally. */
(function(root){'use strict';const {HEROES,DIRS}=root.PixelTankCore;const rect=(c,x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(Math.round(x),Math.round(y),w,h);};
function portrait(c,id,x,y,scale=1){const a=root.PixelQuestCharacters,rows=a.art[id==='explorer'?'hero':id],pal={...a.palette,...a.colors[id]};for(let yy=0;yy<rows.length;yy++)for(let xx=0;xx<rows[yy].length;xx++)if(rows[yy][xx]!=='.')rect(c,x+xx*scale,y+yy*scale,scale,scale,pal[rows[yy][xx]]);}
function tank(c,t,time){c.save();c.translate(Math.round(t.x),Math.round(t.y));c.rotate(t.dir*Math.PI/2);const boss=t.type==='boss',w=boss?30:24,h=boss?32:25,col=t.player?HEROES[t.id].color:({scout:'#78cda7',sniper:'#b19fe6',armor:'#e69b70',boss:'#ce586d',grunt:'#c7b281'}[t.type]);rect(c,-w/2+1,-h/2+2,w,h,'#111b21');for(const side of [-1,1]){const x=side<0?-w/2:w/2-5;rect(c,x,-h/2,5,h,'#1b2630');rect(c,x+1,-h/2,2,h,'#819098');for(let y=-h/2;y<h/2;y+=5)rect(c,x,y+Math.floor(t.tread)%3,5,2,'#46525d');}rect(c,-w/2+5,-h/2+2,w-10,h-4,col);rect(c,-w/2+6,-h/2+3,w-12,3,'#ffffff66');rect(c,-w/2+5,h/2-6,w-10,3,'#00000055');rect(c,-6,-7,12,14,'#192b36');rect(c,-5,-6,10,11,col);rect(c,-4,-6,8,2,'#fff4d677');rect(c,-2,-h/2-5,4,h/2+7,'#1b2a35');rect(c,-1,-h/2-5,2,h/2+5,'#cdd6cb');rect(c,-3,-h/2-6,6,3,'#2a3d48');if(t.player){if(t.id==='mystic'){rect(c,-3,0,6,4,'#f9e4c7');rect(c,-1,0,2,3,'#272834');}else if(t.id==='goku'){rect(c,-4,0,8,5,'#1f4f8b');rect(c,-1,0,2,5,'#ffcf51');}else if(t.id==='dora'){rect(c,-4,0,8,5,'#fff3dd');rect(c,-1,0,2,2,'#ef5350');}else if(t.id==='nezha'){rect(c,-4,0,8,5,'#e54155');rect(c,-3,1,6,2,'#ffd365');}else{rect(c,-3,0,6,4,'#fff1c6');rect(c,-1,0,2,4,col);}}else{rect(c,-2,0,4,3,'#1c2731');}if(t.shotFlash>0){rect(c,-4,-h/2-11,8,4,'#ffce53');rect(c,-1,-h/2-14,2,6,'#fff3b5');}c.restore();if(t.shield>0){c.strokeStyle=t.player?'#8be9ee':'#bfcfe899';c.lineWidth=1;c.strokeRect(Math.round(t.x-w/2-3),Math.round(t.y-h/2-3),w+6,h+6);}if(boss){rect(c,t.x-19,t.y-24,38,3,'#35242b');rect(c,t.x-19,t.y-24,38*Math.max(0,t.hp)/t.maxHp,3,'#f18493');}}
function terrain(c,tile,x,y,level){if(tile==='B'){rect(c,x,y,16,16,'#5a3330');rect(c,x+1,y+1,14,14,'#ae6044');for(let row=0;row<3;row++){rect(c,x,y+row*5+4,16,1,'#6e3d31');rect(c,x+(row%2?4:8),y+row*5,1,5,'#6e3d31');rect(c,x+1,y+row*5,6,1,'#da9770');}}else if(tile==='S'){rect(c,x,y,16,16,'#253c4c');rect(c,x+1,y+1,14,14,'#84979f');rect(c,x+2,y+2,12,2,'#c1cfc9');rect(c,x+12,y+4,2,10,'#536c7a');for(const [a,b]of [[3,5],[10,5],[3,11],[10,11]])rect(c,x+a,y+b,2,2,'#435666');}else if(tile==='W'){rect(c,x,y,16,16,'#245b89');const shift=Math.floor(level)%6;rect(c,x+shift,y+3,8,2,'#5aafc3');rect(c,x+(shift+6)%8,y+10,7,1,'#80cbd3');}else if(tile==='F'){rect(c,x,y,16,16,'#204f43');for(const[a,b]of [[2,1],[8,0],[0,7],[7,7],[11,10]]){rect(c,x+a,y+b,5,5,'#387c51');rect(c,x+a+1,y+b,3,1,'#6da362');}}}
function base(c,b,time){rect(c,b.x-14,b.y-14,28,28,'#122430');rect(c,b.x-12,b.y-12,24,24,b.hp>0?'#c89e50':'#704044');rect(c,b.x-10,b.y-10,20,2,'#fff0a3');rect(c,b.x-3,b.y-8,6,14,'#f8e2a3');rect(c,b.x-9,b.y-5,18,5,'#f8e2a3');rect(c,b.x-7,b.y,4,5,'#f8e2a3');rect(c,b.x+3,b.y,4,5,'#f8e2a3');if(b.shield>0){c.strokeStyle='#9fe8ff';c.lineWidth=2;c.strokeRect(b.x-17,b.y-17,34,34);}}
function projectile(c,s,time){c.save();c.translate(Math.round(s.x),Math.round(s.y));c.rotate(Math.atan2(s.vy,s.vx));if(!s.special){rect(c,-4,-1,7,3,s.friendly?'#fff0aa':'#ff9c73');rect(c,1,-1,2,2,'#fff5d2');}else if(s.kind==='nezha'){rect(c,-7,-5,14,10,'#ffb333');rect(c,-5,-7,10,14,'#ffb333');rect(c,-4,-4,8,8,'#283c38');rect(c,-5,-6,7,2,'#fff0b0');}else if(s.kind==='mystic'){rect(c,-12,-2,19,4,'#ffc36b');rect(c,2,-5,4,10,'#ffe6af');rect(c,6,-3,3,6,'#fff7d4');rect(c,-12,-5,3,10,'#ed9760');}else if(s.kind==='goku'){rect(c,-20,-4,24,8,'#50bde4');rect(c,-17,-2,25,4,'#dffcff');rect(c,-4,-6,10,12,'#89e3f9');rect(c,-2,-3,10,6,'#fff9d8');}else if(s.kind==='dora'){for(let i=0;i<3;i++){const r=7-i;c.strokeStyle=i===0?'#d0f6ff':'#70c8e0';c.lineWidth=1;c.strokeRect(-i*7-r,-r,r*2,r*2);}rect(c,0,-2,4,4,'#f3ffff');}else if(s.kind==='explorer'){rect(c,-9,-4,12,8,'#ef7748');rect(c,-5,-3,12,6,'#ffcb5b');rect(c,0,-2,8,4,'#fff0b7');rect(c,-12,-1,4,3,Math.floor(time*12)%2?'#ffe087':'#c95b41');}else{rect(c,-9,-2,14,4,'#b8e48a');rect(c,0,-1,7,2,'#fff5cb');}c.restore();}
const ICONS={weapon:'★',shield:'S',bomb:'B',freeze:'T',repair:'+',life:'♥'};
function pickup(c,p,time){if(p.life<4&&Math.floor(time*8)%2)return;rect(c,p.x-9,p.y-9,18,18,'#122a35');rect(c,p.x-8,p.y-8,16,16,'#e3be6e');rect(c,p.x-6,p.y-6,12,12,'#273d48');if(p.type==='bomb'){const x=p.x,y=p.y;rect(c,x-4,y-3,9,8,'#090f18');rect(c,x-5,y-1,11,4,'#111c2b');rect(c,x-3,y-2,3,2,'#829ba9');rect(c,x-1,y-5,4,3,'#9f845a');rect(c,x+1,y-7,2,3,'#dfbe74');rect(c,x+3,y-8,3,2,Math.floor(time*8)%2?'#fff3ba':'#ff8651');return;}c.fillStyle='#ffedb6';c.font='bold 12px monospace';c.textAlign='center';c.fillText(ICONS[p.type],p.x,p.y+4);}
root.PixelTankAssets={tank,terrain,base,pickup,portrait,projectile,rect,ICONS};
})(globalThis);
